    #[test]
    fn two_structured_edits_for_one_target_are_refused_but_peers_still_batch() {
        let relationship = |id: &str, value: &str| PrivateEdit::NpcRelationship(
            PrivateNpcRelationshipEdit {
                id: id.to_string(),
                relationship: npc::PersonalRelationship::parse(value).unwrap(),
            },
        );
        let skill = |actor: &str, base: &str, tier: &str| {
            PrivateEdit::SkillSet(skills::SkillSetEdit {
                actor: actor.to_string(),
                base: base.to_string(),
                tier: tier.to_string(),
            })
        };

        // Each of the two replaces that NPC's relationship, so one of them would
        // vanish without a word. The id is matched as the appliers match it.
        assert_eq!(
            structured_edit_target(&relationship("Diego", "friend")),
            structured_edit_target(&relationship(" diego ", "enemy")),
        );

        // Two skills of one character are two different targets — that is what a
        // batch is for — and so are one skill of two characters.
        assert_ne!(
            structured_edit_target(&skill("Hero", "Skill_OneHanded", "Tier2")),
            structured_edit_target(&skill("Hero", "Skill_Bow", "Tier2")),
        );
        assert_ne!(
            structured_edit_target(&skill("Hero", "Skill_Bow", "Tier2")),
            structured_edit_target(&skill("Diego", "Skill_Bow", "Tier2")),
        );
        assert_eq!(
            structured_edit_target(&skill("Hero", "Skill_Bow", "Tier1")),
            structured_edit_target(&skill("Hero", "Skill_Bow", "Tier3")),
        );

        // Adding two items to one inventory is not a target collision at all.
        let add = |path: &str| {
            PrivateEdit::InventoryAddItem(PrivateInventoryAddItemEdit {
                path: path.to_string(),
                count: 1,
                actor_id: None,
            })
        };
        assert!(structured_edit_target(&add("/Script/Angelscript.ItFo_Cheese")).is_none());

        // And end to end: the same segment twice is refused by name, two
        // different segments of one document still share the write.
        let (_dir, path, backend) = progression_fixture(
            "G1R-glossary-pair.sav",
            glossary_progression_payload(),
        );
        let data = fs::read(path).unwrap();
        let segment = |segment: &str, unlocked: bool| Edit {
            path: "private.glossary.setSegment".to_string(),
            value: json!({
                "documentClass": "/Script/Angelscript.Document_Glossary_Meatbug",
                "segmentClass": segment,
                "unlocked": unlocked,
            }),
        };
        let entry2 = segment(
            "/Script/Angelscript.DocumentSegment_Glossary_Meatbug_Entry2",
            true,
        );
        let entry2_again = segment(
            "/Script/Angelscript.DocumentSegment_Glossary_Meatbug_Entry2",
            false,
        );
        let unlock = segment(
            "/Script/Angelscript.DocumentSegment_Glossary_Meatbug_Unlock",
            false,
        );

        let error = apply_private_edits(&data, &[&entry2, &entry2_again], Some(&backend))
            .unwrap_err();
        let CoreError::UnsupportedEdit(message) = &error else {
            panic!("expected the pair to be refused, got {error:?}");
        };
        assert!(
            message.contains("glossary segment"),
            "the refusal has to say what the two share, got {message:?}"
        );
        apply_private_edits(&data, &[&entry2, &unlock], Some(&backend))
            .expect("two different segments of one document still share a write");
    }

    #[test]
    fn glossary_set_segment_refuses_a_peer_write_to_the_quest_state_it_sets() {
        let (_dir, path, backend) = progression_fixture(
            "G1R-glossary-standalone.sav",
            glossary_progression_payload(),
        );
        let data = fs::read(path).unwrap();
        // No questStatePath: the write derives the matching leaf from the
        // document and segment and sets it, exactly as if one had been supplied.
        let glossary = Edit {
            path: "private.glossary.setSegment".to_string(),
            value: json!({
                "documentClass": "/Script/Angelscript.Document_Glossary_Meatbug",
                "segmentClass": "/Script/Angelscript.DocumentSegment_Glossary_Meatbug_Entry2",
                "unlocked": true
            }),
        };
        let peer = Edit {
            path: "private.typed.setValue".to_string(),
            value: json!({
                "path": [
                    "QuestDataByClass",
                    "{/Script/Angelscript.Quest_OldCamp_SLEEPER}",
                    "CurrentState"
                ],
                "value": "EQuestState::Available"
            }),
        };

        // Sharing a write would set that CurrentState twice and report both edits
        // as applied while one of them is discarded, whichever order they run in.
        for pair in [[&glossary, &peer], [&peer, &glossary]] {
            let error = apply_private_edits(&data, &pair, Some(&backend)).unwrap_err();
            let CoreError::UnsupportedEdit(message) = &error else {
                panic!("expected the pair to be refused, got {error:?}");
            };
            assert!(
                message.contains("private.typed.setValue")
                    && message.contains("private.glossary.setSegment"),
                "the refusal has to name both edits, got {message:?}"
            );
        }

        // Alone it goes through, and sets that leaf itself.
        let edited = apply_private_edits(&data, &[&glossary], Some(&backend)).unwrap();
        let payload = decoded_private_payload_for_tests(&edited, &backend);
        assert!(
            find_subslice(&payload, b"DocumentSegment_Glossary_Meatbug_Entry2").is_some(),
            "the unlocked segment is missing from the written payload"
        );
        let root = properties::parse_private_root(&payload).unwrap();
        let state = properties::resolve(
            &root.properties,
            &properties::parse_path(&[
                "QuestDataByClass".to_string(),
                "{/Script/Angelscript.Quest_CreaturesGlossary_MeatbugGlossary_MeatbugEntry2}"
                    .to_string(),
                "CurrentState".to_string(),
            ])
            .unwrap(),
        )
        .unwrap();
        assert_eq!(
            state.value,
            properties::PropertyValue::Enum("EQuestState::Succeeded".to_string())
        );
    }

    #[test]
    fn query_progression_lists_quests_with_state_paths() {
        let dir = tempdir().unwrap();
        let path = dir.path().join("G1R-quests.sav");
        let private_payload = quest_map_payload();
        let seed_compressed = b"seed".to_vec();
        let stream = compressed_stream_with_one_chunk(&seed_compressed, private_payload.len());
        fs::write(
            &path,
            build_gsav(2, &public_payload("Slot"), &stream, &[0, 0, 0, 0]),
        )
        .unwrap();
        let backend = PrefixCodecBackend {
            seed_compressed,
            seed_uncompressed: private_payload,
        };

        let value =
            query_progression(&path, &json!({ "section": "quests" }), Some(&backend)).unwrap();
        assert_eq!(value["section"], "quests");
        assert_eq!(value["total"], 2);
        assert_eq!(value["stateCounts"]["Running"], 1);
        assert_eq!(value["stateCounts"]["Available"], 1);
        // Sorted by class path: BanditsCamp before OldCamp.
        let first = &value["quests"][0];
        assert_eq!(
            first["questClass"],
            "/Script/Angelscript.Quest_BanditsCamp_BANDITSTRUST"
        );
        assert_eq!(first["id"], "Quest_BanditsCamp_BANDITSTRUST");
        assert_eq!(first["group"], "BanditsCamp");
        assert_eq!(first["name"], "BANDITSTRUST");
        assert_eq!(first["currentState"], "EQuestState::Available");
        assert_eq!(
            first["statePath"],
            json!([
                "QuestDataByClass",
                "{/Script/Angelscript.Quest_BanditsCamp_BANDITSTRUST}",
                "CurrentState"
            ])
        );

        // Query filter + paging.
        let filtered = query_progression(
            &path,
            &json!({ "section": "quests", "query": "sleeper" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(filtered["total"], 1);
        assert_eq!(filtered["quests"][0]["name"], "SLEEPER");

        // The statePath round-trips through the existing setValue write.
        let output_path = dir.path().join("G1R-quests-out.sav");
        let response = write_save_with_codec_backend(
            &path,
            &[json!({
                "path": "private.typed.setValue",
                "value": {
                    "path": [
                        "QuestDataByClass",
                        "{/Script/Angelscript.Quest_BanditsCamp_BANDITSTRUST}",
                        "CurrentState"
                    ],
                    "value": "EQuestState::Succeeded"
                }
            })],
            false,
            Some(&output_path),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(response["editsApplied"], 1);
        let after = query_progression(
            &output_path,
            &json!({ "section": "quests", "query": "banditstrust" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(after["quests"][0]["currentState"], "EQuestState::Succeeded");
    }

    #[test]
    fn query_progression_quests_state_and_group_filters() {
        // Fixture: OldCamp_SLEEPER Running, BanditsCamp_BANDITSTRUST Available.
        let dir = tempdir().unwrap();
        let path = dir.path().join("G1R-filter.sav");
        let private_payload = quest_map_payload();
        let seed_compressed = b"seed".to_vec();
        let stream = compressed_stream_with_one_chunk(&seed_compressed, private_payload.len());
        fs::write(
            &path,
            build_gsav(2, &public_payload("Slot"), &stream, &[0, 0, 0, 0]),
        )
        .unwrap();
        let backend = PrefixCodecBackend {
            seed_compressed,
            seed_uncompressed: private_payload,
        };

        // No filters: both facets cover all entries.
        let base =
            query_progression(&path, &json!({ "section": "quests" }), Some(&backend)).unwrap();
        assert_eq!(base["groupCounts"]["BanditsCamp"], 1);
        assert_eq!(base["groupCounts"]["OldCamp"], 1);
        assert_eq!(base["stateCounts"]["Running"], 1);
        assert_eq!(base["stateCounts"]["Available"], 1);

        // state:"Running" → 1 hit (SLEEPER).
        // groupCounts respects query+state (not group), so only Running entries counted.
        // stateCounts respects query+group (no group filter), so all entries counted.
        let running = query_progression(
            &path,
            &json!({ "section": "quests", "state": "Running" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(running["total"], 1);
        assert_eq!(running["quests"][0]["name"], "SLEEPER");
        // groupCounts: only Running entries → OldCamp=1, BanditsCamp absent.
        assert_eq!(running["groupCounts"]["OldCamp"], 1);
        assert!(running["groupCounts"]["BanditsCamp"].is_null());
        // stateCounts: no group filter applied → all entries.
        assert_eq!(running["stateCounts"]["Running"], 1);
        assert_eq!(running["stateCounts"]["Available"], 1);

        // state:"EQuestState::Running" (full form) → same result.
        let running_full = query_progression(
            &path,
            &json!({ "section": "quests", "state": "EQuestState::Running" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(running_full["total"], 1);
        assert_eq!(running_full["quests"][0]["name"], "SLEEPER");

        // state:"running" (case-insensitive) → same result.
        let running_lower = query_progression(
            &path,
            &json!({ "section": "quests", "state": "running" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(running_lower["total"], 1);
        assert_eq!(running_lower["quests"][0]["name"], "SLEEPER");

        // group:"banditscamp" → 1 hit (BANDITSTRUST).
        // stateCounts respects query+group → only BanditsCamp entries → Available=1 only.
        // groupCounts respects query+state (no state filter) → all entries.
        let by_group = query_progression(
            &path,
            &json!({ "section": "quests", "group": "banditscamp" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(by_group["total"], 1);
        assert_eq!(by_group["quests"][0]["name"], "BANDITSTRUST");
        assert_eq!(by_group["stateCounts"]["Available"], 1);
        assert!(by_group["stateCounts"]["Running"].is_null());
        assert_eq!(by_group["groupCounts"]["BanditsCamp"], 1);
        assert_eq!(by_group["groupCounts"]["OldCamp"], 1);

        // Combined state=Running + group=BanditsCamp → 0 results (Running quest is in OldCamp).
        // stateCounts: query+group(BanditsCamp) → only BanditsCamp entry → Available=1.
        // groupCounts: query+state(Running) → only Running entry → OldCamp=1.
        let no_match = query_progression(
            &path,
            &json!({ "section": "quests", "state": "Running", "group": "BanditsCamp" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(no_match["total"], 0);
        // stateCounts sees only BanditsCamp entries (Available).
        assert_eq!(no_match["stateCounts"]["Available"], 1);
        assert!(no_match["stateCounts"]["Running"].is_null());
        // groupCounts sees only Running entries (OldCamp).
        assert_eq!(no_match["groupCounts"]["OldCamp"], 1);
        assert!(no_match["groupCounts"]["BanditsCamp"].is_null());
    }

    // ── Task 6 helpers ──────────────────────────────────────────────────────

    fn private_double_property(name: &str, value: f64) -> Vec<u8> {
        let mut out = fstring(name);
        out.extend_from_slice(&fstring("DoubleProperty"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&8u32.to_le_bytes());
        out.push(0);
        out.extend_from_slice(&value.to_le_bytes());
        out
    }

    fn private_struct_property(name: &str, struct_type: &str, body: &[u8], flags: u8) -> Vec<u8> {
        let mut out = fstring(name);
        out.extend_from_slice(&fstring("StructProperty"));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring(struct_type));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring("/Script/G1R"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&(body.len() as u32).to_le_bytes());
        out.push(flags);
        out.extend_from_slice(body);
        out
    }

    fn name_keyed_struct_map(map_name: &str, entries: &[(&str, Vec<u8>)]) -> Vec<u8> {
        name_keyed_struct_map_of(map_name, "KnowledgeSet", entries)
    }

    fn name_keyed_struct_map_of(
        map_name: &str,
        struct_type: &str,
        entries: &[(&str, Vec<u8>)],
    ) -> Vec<u8> {
        let mut map_body = 0u32.to_le_bytes().to_vec();
        map_body.extend_from_slice(&(entries.len() as u32).to_le_bytes());
        for (key, value_props) in entries {
            map_body.extend_from_slice(&fstring(key));
            map_body.extend_from_slice(value_props);
            map_body.extend_from_slice(&fstring("None"));
        }
        let mut out = fstring(map_name);
        out.extend_from_slice(&fstring("MapProperty"));
        out.extend_from_slice(&2u32.to_le_bytes());
        out.extend_from_slice(&fstring("NameProperty"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&fstring("StructProperty"));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring(struct_type));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring("/Script/G1R"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&(map_body.len() as u32).to_le_bytes());
        out.push(0);
        out.extend_from_slice(&map_body);
        out
    }

    fn string_keyed_instanced_struct_map(
        map_name: &str,
        actual_type: &str,
        entries: &[(&str, Vec<u8>)],
    ) -> Vec<u8> {
        let mut map_body = 0u32.to_le_bytes().to_vec();
        map_body.extend_from_slice(&(entries.len() as u32).to_le_bytes());
        for (key, value_props) in entries {
            map_body.extend_from_slice(&fstring(key));
            let mut instance_body = value_props.clone();
            instance_body.extend_from_slice(&fstring("None"));
            map_body.extend_from_slice(&fstring(actual_type));
            map_body.extend_from_slice(&(instance_body.len() as u32).to_le_bytes());
            map_body.extend_from_slice(&instance_body);
        }
        let mut out = fstring(map_name);
        out.extend_from_slice(&fstring("MapProperty"));
        out.extend_from_slice(&2u32.to_le_bytes());
        out.extend_from_slice(&fstring("StrProperty"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&fstring("StructProperty"));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring("InstancedStruct"));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring("/Script/StructUtils"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&(map_body.len() as u32).to_le_bytes());
        out.push(0);
        out.extend_from_slice(&map_body);
        out
    }

    fn name_keyed_int_map(map_name: &str, entries: &[(&str, i32)]) -> Vec<u8> {
        let mut map_body = 0u32.to_le_bytes().to_vec();
        map_body.extend_from_slice(&(entries.len() as u32).to_le_bytes());
        for (key, value) in entries {
            map_body.extend_from_slice(&fstring(key));
            map_body.extend_from_slice(&value.to_le_bytes());
        }
        let mut out = fstring(map_name);
        out.extend_from_slice(&fstring("MapProperty"));
        out.extend_from_slice(&2u32.to_le_bytes());
        out.extend_from_slice(&fstring("NameProperty"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&fstring("IntProperty"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&(map_body.len() as u32).to_le_bytes());
        out.push(0);
        out.extend_from_slice(&map_body);
        out
    }

    fn object_keyed_struct_map(
        map_name: &str,
        struct_type: &str,
        entries: &[(&str, Vec<u8>)],
    ) -> Vec<u8> {
        let mut map_body = 0u32.to_le_bytes().to_vec();
        map_body.extend_from_slice(&(entries.len() as u32).to_le_bytes());
        for (key, value_props) in entries {
            map_body.extend_from_slice(&fstring(key));
            map_body.extend_from_slice(value_props);
            map_body.extend_from_slice(&fstring("None"));
        }
        let mut out = fstring(map_name);
        out.extend_from_slice(&fstring("MapProperty"));
        out.extend_from_slice(&2u32.to_le_bytes());
        out.extend_from_slice(&fstring("ObjectProperty"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&fstring("StructProperty"));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring(struct_type));
        out.extend_from_slice(&1u32.to_le_bytes());
        out.extend_from_slice(&fstring("/Script/G1R"));
        out.extend_from_slice(&0u32.to_le_bytes());
        out.extend_from_slice(&(map_body.len() as u32).to_le_bytes());
        out.push(0);
        out.extend_from_slice(&map_body);
        out
    }

    fn story_progression_payload() -> Vec<u8> {
        let values = name_keyed_int_map(
            "StoryPropertyValues",
            &[
                ("Stone_OreArmor", 1_767_047),
                ("Chapter", 2),
                ("Unknown_Timer_Name", 17),
            ],
        );
        let by_class = object_keyed_struct_map(
            "SaveDataByStoryClass",
            "SingleStorySaveGameData",
            &[("/Script/Angelscript.StoryG1R", values)],
        );
        let mut time_body = private_double_property("TotalSeconds", 1_875_587.943_7);
        time_body.extend_from_slice(&fstring("None"));
        let current_time = private_struct_property("CurrentTime", "InGameTime", &time_body, 0);
        let generic = string_keyed_instanced_struct_map(
            "m_GenericData",
            "/Script/G1R.StorySaveGameData",
            &[("Story", by_class), ("GameTime", current_time)],
        );

        let mut payload = fstring("/Script/Angelscript.GothicFinalDataGame");
        payload.push(0);
        payload.extend_from_slice(&generic);
        payload.extend_from_slice(&fstring("None"));
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload
    }

    #[test]
    fn query_progression_story_and_all_data_surface_scalar_story_map_entries() {
        let (_dir, path, backend) =
            progression_fixture("G1R-story.sav", story_progression_payload());

        let story = query_progression(
            &path,
            &json!({ "section": "story", "query": "Stone" }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(story["section"], "story");
        assert_eq!(story["includeUnset"], false);
        assert_eq!(story["total"], 1);
        assert_eq!(story["storedTotal"], 3);
        assert_eq!(story["catalogTotal"], 470);
        assert_eq!(story["unsetTotal"], 468);
        assert_eq!(story["unknownStoredTotal"], 1);
        assert_eq!(story["writable"], true);
        assert_eq!(story["entries"][0]["id"], "Stone_OreArmor");
        assert_eq!(story["entries"][0]["rawValue"], 1_767_047);
        assert_eq!(story["entries"][0]["stored"], true);
        assert_eq!(story["entries"][0]["semanticType"], "timeMarker");
        assert_eq!(story["entries"][0]["declaredType"], "FInGameTime");
        assert_eq!(story["currentGameTimeSeconds"], 1_875_587.943_7);
        assert_eq!(
            story["entries"][0]["path"],
            json!([
                "m_GenericData",
                "{Story}",
                "SaveDataByStoryClass",
                "{/Script/Angelscript.StoryG1R}",
                "StoryPropertyValues",
                "{Stone_OreArmor}",
            ])
        );

        let unknown_story = query_progression(
            &path,
            &json!({
                "section": "story",
                "semanticType": "unknown",
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(unknown_story["semanticType"], "unknown");
        assert_eq!(unknown_story["total"], 1);
        assert_eq!(unknown_story["entries"][0]["id"], "Unknown_Timer_Name");
        assert_eq!(unknown_story["entries"][0]["semanticType"], "unknown");
        assert_eq!(unknown_story["entries"][0]["declaredType"], "unknown");
        assert_eq!(unknown_story["semanticTypeCounts"]["unknown"], 1);
        assert_eq!(unknown_story["storedSemanticTypeCounts"]["unknown"], 1);

        let exact_type_filter = query_progression(
            &path,
            &json!({
                "section": "story",
                "semanticType": "timemarker",
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(exact_type_filter["semanticType"], "timemarker");
        assert_eq!(exact_type_filter["total"], 0);

        let catalog = query_progression(
            &path,
            &json!({
                "section": "story",
                "includeUnset": true,
                "offset": 0,
                "limit": 1000,
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(catalog["includeUnset"], true);
        assert_eq!(catalog["total"], 471);
        assert_eq!(catalog["count"], 471);
        assert_eq!(catalog["catalogTotal"], 470);
        assert_eq!(catalog["unsetTotal"], 468);
        assert_eq!(catalog["unknownStoredTotal"], 1);
        let unset = catalog["entries"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["id"] == "AfterCinematic_Nyras")
            .unwrap();
        assert_eq!(unset["stored"], false);
        assert_eq!(unset["rawValue"], Value::Null);
        assert_eq!(unset["path"], json!([]));

        // The All-data UI sends the explicit `all` kind value. Pin that exact
        // request shape as well as the scalar facet below, so a map-entry hit
        // cannot disappear merely because the kind selector is at its default.
        let all_kinds = search_typed_properties(
            &path,
            &json!({
                "query": "Stone_OreArmor",
                "includeNodes": true,
                "source": "private",
                "kind": "all",
                "offset": 0,
                "limit": 20,
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(all_kinds["total"], 1);
        assert_eq!(all_kinds["results"][0]["kind"], "mapEntry");
        assert_eq!(all_kinds["results"][0]["editable"], false);

        let scalar = search_typed_properties(
            &path,
            &json!({
                "query": "Stone_OreArmor",
                "includeNodes": true,
                "source": "private",
                "kind": "scalar",
                "offset": 0,
                "limit": 20,
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(scalar["total"], 1);
        let row = &scalar["results"][0];
        assert_eq!(row["kind"], "mapEntry");
        assert_eq!(row["type"], "IntProperty");
        assert_eq!(row["childCount"], 0);
        assert_eq!(row["editable"], false);
        assert_eq!(row["editValue"], Value::Null);
        assert_eq!(
            row["path"],
            json!([
                "m_GenericData",
                "{Story}",
                "SaveDataByStoryClass",
                "{/Script/Angelscript.StoryG1R}",
                "StoryPropertyValues",
                "{Stone_OreArmor}",
            ])
        );

        let editable = search_typed_properties(
            &path,
            &json!({
                "query": "Stone_OreArmor",
                "includeNodes": true,
                "source": "private",
                "kind": "scalar",
                "editable": true,
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(editable["total"], 0);

        let container = search_typed_properties(
            &path,
            &json!({
                "query": "Stone_OreArmor",
                "includeNodes": true,
                "source": "private",
                "kind": "container",
            }),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(container["total"], 1);
        assert_eq!(container["results"][0]["kind"], "mapEntry");
        assert_eq!(container["results"][0]["editable"], false);
    }

