    #[test]
    fn write_save_applies_inventory_remove_item() {
        // End to end: write_save parses the edit, applies it to the typed
        // payload, recompresses, and the output save's inventory summary no
        // longer contains the removed item.
        let dir = tempdir().unwrap();
        let path = dir.path().join("G1R-001.sav");
        let output_path = dir.path().join("G1R-001-out.sav");
        let private_payload = typed_inventory_private_payload(&[], &default_main_slots());
        let seed_compressed = b"seed-remove".to_vec();
        let stream = compressed_stream_with_one_chunk(&seed_compressed, private_payload.len());
        fs::write(
            &path,
            build_gsav(2, &public_payload("Slot A"), &stream, &[0, 0, 0, 0]),
        )
        .unwrap();
        let backend = PrefixCodecBackend {
            seed_compressed,
            seed_uncompressed: private_payload,
        };

        let response = write_save_with_codec_backend(
            &path,
            &[json!({
                "path": "private.inventory.removeItem",
                "value": { "path": "/Script/Angelscript.ItMi_Orenugget" }
            })],
            false,
            Some(&output_path),
            Some(&backend),
        )
        .unwrap();
        assert_eq!(response["editsApplied"], 1);

        let value =
            inspect_save_with_codec_backend(&output_path, true, Some(&backend), None).unwrap();
        let items = value["private"]["inventory"]["items"].as_array().unwrap();
        assert!(
            !items
                .iter()
                .any(|item| item["path"] == "/Script/Angelscript.ItMi_Orenugget"),
            "output save inventory still has removed item: {items:?}"
        );
        assert!(
            items
                .iter()
                .any(|item| item["path"] == "/Script/Angelscript.ItFo_Apple"),
            "output save inventory missing survivor: {items:?}"
        );
    }

    /// Resolve the given NPC's inventory and report whether any slot in any of
    /// its containers holds an item whose `m_SlotData.m_ItemDefinition` equals
    /// `item_path`. Mirrors the player-inventory slot traversal but scoped to
    /// the NPC inventory resolved by GlobalId (Task 14 path).
    fn npc_inventory_contains(payload: &[u8], npc_id: &str, item_path: &str) -> bool {
        let root = properties::parse_private_root(payload).expect("payload re-parses");
        let inventory_path =
            npc::npc_inventory_path(&root, npc_id).expect("npc has an inventory path");
        let resolve_child = |suffix: &[&str]| -> Option<properties::PropertyValue> {
            let mut segs = inventory_path.clone();
            segs.extend(suffix.iter().map(|s| s.to_string()));
            let parsed = properties::parse_path(&segs).ok()?;
            properties::resolve(&root.properties, &parsed)
                .ok()
                .map(|prop| prop.value.clone())
        };
        let Some(properties::PropertyValue::Array {
            elements: containers,
        }) = resolve_child(&["m_Values", "Items"])
        else {
            return false;
        };
        for index in 0..containers.len() {
            let segment = format!("[{index}]");
            if let Some(properties::PropertyValue::Array { elements: slots }) =
                resolve_child(&["m_Values", "Items", &segment, "m_Slots"])
            {
                if slots
                    .iter()
                    .any(|slot| slot_item_definition(slot) == Some(item_path))
                {
                    return true;
                }
            }
        }
        false
    }

    /// First item definition path held in the NPC's MainContainer (the container
    /// the count edit targets), or `None` if it has no items.
    fn first_npc_main_container_item(payload: &[u8], npc_id: &str) -> Option<String> {
        let root = properties::parse_private_root(payload).expect("payload re-parses");
        let inventory_path = npc::npc_inventory_path(&root, npc_id)?;
        let slots_suffix = main_container_slots_suffix(&root, &inventory_path).ok()?;
        let mut segs = inventory_path;
        segs.extend_from_slice(&slots_suffix);
        let slots =
            properties::resolve(&root.properties, &properties::parse_path(&segs).ok()?).ok()?;
        let properties::PropertyValue::Array { elements: slots } = &slots.value else {
            return None;
        };
        slots
            .iter()
            .find_map(|slot| slot_item_definition(slot).map(str::to_string))
    }

    /// The `m_ItemCount` of the NPC MainContainer slot whose
    /// `m_SlotData.m_ItemDefinition` equals `item_path`.
    fn npc_item_count(payload: &[u8], npc_id: &str, item_path: &str) -> Option<i32> {
        let root = properties::parse_private_root(payload).expect("payload re-parses");
        let inventory_path = npc::npc_inventory_path(&root, npc_id)?;
        let slots_suffix = main_container_slots_suffix(&root, &inventory_path).ok()?;
        let mut segs = inventory_path;
        segs.extend_from_slice(&slots_suffix);
        let slots =
            properties::resolve(&root.properties, &properties::parse_path(&segs).ok()?).ok()?;
        let properties::PropertyValue::Array { elements: slots } = &slots.value else {
            return None;
        };
        slots
            .iter()
            .find(|slot| slot_item_definition(slot) == Some(item_path))
            .and_then(slot_item_count)
    }

    #[test]
    #[ignore = "needs GORESAVE_PAYLOAD_BIN=<a decompressed host.bin>"]
    fn set_item_count_on_npc_updates_typed_slot() {
        let path = std::env::var("GORESAVE_PAYLOAD_BIN").expect("set GORESAVE_PAYLOAD_BIN");
        let mut payload = std::fs::read(path).unwrap();
        let id = "Lizard-WP_EF_SCSLOPE_LIZARD_SPAWN_01-1";
        let len_before = payload.len();

        // Find an item already in this NPC's MainContainer.
        let item = first_npc_main_container_item(&payload, id)
            .expect("NPC MainContainer should hold at least one item");

        apply_private_inventory_item_count_edit_to_payload(
            &mut payload,
            &PrivateInventoryItemCountEdit {
                id: None,
                path: Some(item.clone()),
                count: 42,
                actor_id: Some(id.into()),
                slot_id: None,
                container_type: None,
            },
        )
        .unwrap();

        // Fixed-size IntProperty patch: payload length is unchanged and the save
        // still parses to its full length.
        assert_eq!(payload.len(), len_before, "in-place patch must not resize");
        let root = properties::parse_private_root(&payload).unwrap();
        assert_eq!(root.consumed, payload.len(), "re-parse after count edit");

        assert_eq!(
            npc_item_count(&payload, id, &item),
            Some(42),
            "NPC slot m_ItemCount should be 42 after the edit"
        );
    }

    #[test]
    #[ignore = "needs GORESAVE_PAYLOAD_BIN=<a decompressed host.bin>"]
    fn add_then_remove_item_on_npc_roundtrips() {
        let path = std::env::var("GORESAVE_PAYLOAD_BIN").expect("set GORESAVE_PAYLOAD_BIN");
        let mut payload = std::fs::read(path).unwrap();
        let id = "Lizard-WP_EF_SCSLOPE_LIZARD_SPAWN_01-1";
        let item = "ItFo_Cheese";

        // Sanity: the NPC inventory must not already hold the test item.
        assert!(
            !npc_inventory_contains(&payload, id, item),
            "precondition: NPC must not already hold {item}"
        );

        // Add the item to the NPC's inventory (not the player's).
        apply_private_inventory_add_item_to_payload(
            &mut payload,
            &PrivateInventoryAddItemEdit {
                path: item.to_string(),
                count: 3,
                actor_id: Some(id.to_string()),
            },
        )
        .unwrap();
        // Whole payload re-parses cleanly after the splice (size cascade intact).
        let root = properties::parse_private_root(&payload).unwrap();
        assert_eq!(root.consumed, payload.len(), "re-parse after add");
        assert!(
            npc_inventory_contains(&payload, id, item),
            "NPC inventory should contain {item} after add"
        );

        // Remove it again from the same NPC inventory.
        apply_private_inventory_remove_item_to_payload(
            &mut payload,
            &PrivateInventoryRemoveItemEdit {
                path: item.to_string(),
                actor_id: Some(id.to_string()),
                container_type: None,
                slot_id: None,
            },
        )
        .unwrap();
        let root = properties::parse_private_root(&payload).unwrap();
        assert_eq!(root.consumed, payload.len(), "re-parse after remove");
        assert!(
            !npc_inventory_contains(&payload, id, item),
            "NPC inventory should no longer contain {item} after remove"
        );
    }

    #[test]
    fn parse_private_inventory_remove_item_rejects_two_in_batch() {
        // Two removeItem edits in one batch are two structural edits.
        let dir = tempdir().unwrap();
        let path = dir.path().join("G1R-001.sav");
        let private_payload = typed_inventory_private_payload(&[], &default_main_slots());
        let seed_compressed = b"seed-2remove".to_vec();
        let stream = compressed_stream_with_one_chunk(&seed_compressed, private_payload.len());
        fs::write(
            &path,
            build_gsav(2, &public_payload("Slot A"), &stream, &[0, 0, 0, 0]),
        )
        .unwrap();
        let backend = PrefixCodecBackend {
            seed_compressed,
            seed_uncompressed: private_payload,
        };

        let response = write_save_with_codec_backend(
            &path,
            &[
                json!({
                    "path": "private.inventory.removeItem",
                    "value": { "path": "/Script/Angelscript.ItMi_Orenugget" }
                }),
                json!({
                    "path": "private.inventory.removeItem",
                    "value": { "path": "/Script/Angelscript.ItFo_Apple" }
                }),
            ],
            false,
            None,
            Some(&backend),
        )
        .unwrap();
        assert_eq!(response["editsApplied"], 2);

        // Each removal matches its own item path against the payload it is handed,
        // so the first one's slot renumbering cannot retarget the second.
        let written = fs::read(&path).unwrap();
        let payload = decoded_private_payload_for_tests(&written, &backend);
        for gone in [
            b"/Script/Angelscript.ItMi_Orenugget".as_slice(),
            b"/Script/Angelscript.ItFo_Apple".as_slice(),
        ] {
            assert!(
                find_subslice(&payload, gone).is_none(),
                "removed item is still in the written payload: {}",
                String::from_utf8_lossy(gone)
            );
        }
    }

    #[test]
    fn parse_private_inventory_remove_item_rejects_mixed_with_add_item() {
        // addItem + removeItem in one batch counts as two structural edits.
        let dir = tempdir().unwrap();
        let path = dir.path().join("G1R-001.sav");
        let private_payload = typed_inventory_private_payload(&[], &default_main_slots());
        let seed_compressed = b"seed-mixed-rm".to_vec();
        let stream = compressed_stream_with_one_chunk(&seed_compressed, private_payload.len());
        fs::write(
            &path,
            build_gsav(2, &public_payload("Slot A"), &stream, &[0, 0, 0, 0]),
        )
        .unwrap();
        let backend = PrefixCodecBackend {
            seed_compressed,
            seed_uncompressed: private_payload,
        };

        let response = write_save_with_codec_backend(
            &path,
            &[
                json!({
                    "path": "private.inventory.addItem",
                    "value": { "path": "/Script/Angelscript.ItFo_Cheese", "count": 1 }
                }),
                json!({
                    "path": "private.inventory.removeItem",
                    "value": { "path": "/Script/Angelscript.ItMi_Orenugget" }
                }),
            ],
            false,
            None,
            Some(&backend),
        )
        .unwrap();
        assert_eq!(response["editsApplied"], 2);

        let written = fs::read(&path).unwrap();
        let payload = decoded_private_payload_for_tests(&written, &backend);
        assert!(
            find_subslice(&payload, b"/Script/Angelscript.ItFo_Cheese").is_some(),
            "the added item is missing from the written payload"
        );
        assert!(
            find_subslice(&payload, b"/Script/Angelscript.ItMi_Orenugget").is_none(),
            "the removed item is still in the written payload"
        );
    }

    #[test]
    fn parse_difficulty_settings_reads_preset_and_bools() {
        let mut payload = Vec::new();
        payload.extend_from_slice(&fstring("m_difficultyPreset"));
        payload.extend_from_slice(&fstring("ClassProperty"));
        payload.extend_from_slice(&fstring("/Script/Angelscript.DifficultyPreset_Custom"));
        payload.extend_from_slice(&fstring("m_customCombatSettings"));
        payload.extend_from_slice(&fstring("ClassProperty"));
        payload.extend_from_slice(&fstring(
            "/Script/Angelscript.CombatDifficultySettings_Hard",
        ));
        payload.extend_from_slice(&fstring("m_FakeSloppyCombos"));
        payload.extend_from_slice(&fstring("BoolProperty"));
        payload.extend_from_slice(&[0u8; 8]); // array_index + size
        payload.push(properties::TAG_FLAG_BOOL_TRUE); // bool tag bit = true
        payload.extend_from_slice(&fstring("m_PermanentDeath"));
        payload.extend_from_slice(&fstring("BoolProperty"));
        payload.extend_from_slice(&[0u8; 8]);
        payload.push(0); // false

        let d = parse_difficulty_settings(&payload);
        assert_eq!(d.preset.as_deref(), Some("DifficultyPreset_Custom"));
        assert_eq!(d.combat.as_deref(), Some("CombatDifficultySettings_Hard"));
        assert_eq!(d.flow_helper, Some(true));
        assert_eq!(d.permadeath, Some(false));
    }

    #[test]
    fn parse_difficulty_settings_reads_permadeath_alternate_spelling() {
        let mut payload = Vec::new();
        payload.extend_from_slice(&fstring("m_difficultyPreset"));
        payload.extend_from_slice(&fstring("ClassProperty"));
        payload.extend_from_slice(&fstring("/Script/Angelscript.DifficultyPreset_Custom"));
        // Permadeath stored under the alternate spelling `m_PermaDeath`.
        payload.extend_from_slice(&fstring("m_PermaDeath"));
        payload.extend_from_slice(&fstring("BoolProperty"));
        payload.extend_from_slice(&[0u8; 8]); // array_index + size
        payload.push(properties::TAG_FLAG_BOOL_TRUE); // bool tag bit = true

        let d = parse_difficulty_settings(&payload);
        assert_eq!(d.permadeath, Some(true));
    }

    #[test]
    fn parse_difficulty_settings_bool_only_true_on_0x10_bit() {
        // A FALSE BoolProperty whose tag byte carries another flag (0x08) must
        // read false — only the 0x10 (TAG_FLAG_BOOL_TRUE) bit means true. A
        // "nonzero" test would misread it and a later save would flip it on.
        let mut payload = Vec::new();
        payload.extend_from_slice(&fstring("m_FakeSloppyCombos"));
        payload.extend_from_slice(&fstring("BoolProperty"));
        payload.extend_from_slice(&[0u8; 8]);
        payload.push(0x08); // a non-0x10 flag; the bool value is FALSE
        let d = parse_difficulty_settings(&payload);
        assert_eq!(d.flow_helper, Some(false));
    }

    #[test]
    fn difficulty_for_gsav_bytes_none_for_non_gsav() {
        assert!(difficulty_for_gsav_bytes(b"NOPE").is_none());
    }
